starter.css:
.cadastro {
  max-width: 32rem;
  margin: 2rem auto;
  padding: 1.5rem;
  font-family: system-ui, sans-serif;
}
.campo {
  display: grid;
  gap: 0.35rem;
  margin-bottom: 1rem;
}
label {
  font-weight: 600;
}
input,
select {
  padding: 0.6rem 0.7rem;
  border: 1px solid #475569;
  border-radius: 0.4rem;
  font: inherit;
}
button {
  padding: 0.65rem 1rem;
  border: 0;
  border-radius: 0.4rem;
  background: #1d4ed8;
  color: #ffffff;
  font: inherit;
  cursor: pointer;
}

